import { PrismaClient } from '@prisma/client';

const globalForPrisma = globalThis;

let prisma;
try {
  prisma =
    globalForPrisma.prisma ||
    new PrismaClient({
      log: process.env.NODE_ENV === 'development' ? ['query', 'error', 'warn'] : ['error'],
    });
  if (process.env.NODE_ENV !== 'production') globalForPrisma.prisma = prisma;
} catch (error) {
  // Prisma engines are generated by `prisma generate`, which requires a
  // network connection to download binaries. In environments where that has
  // not been run (e.g. this build without a DATABASE_URL), export a stub so
  // the app still builds. Actual calls will throw a clear error.
  console.warn(
    'PrismaClient could not be initialized. Run `npx prisma generate` after configuring DATABASE_URL.',
  );
  prisma = new Proxy(
    {},
    {
      get() {
        throw new Error(
          'Prisma is not initialized. Run `npx prisma generate` and configure DATABASE_URL before using the database.',
        );
      },
    },
  );
}

export const prismaClient = prisma;
export { prisma };
export default prisma;
